import java.util.*;import java.util.concurrent.*;import java.time.*;import java.math.BigDecimal;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import com.project.system.service.*;import com.project.web.controller.system.MerchantGatewayController;import com.fasterxml.jackson.databind.JsonNode;
public class CampusPaymentChannelIntegration{
 @org.springframework.context.annotation.Configuration @org.springframework.transaction.annotation.EnableTransactionManagement static class Config{
 @org.springframework.context.annotation.Bean public javax.sql.DataSource dataSource(){return new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:mysql://127.0.0.1:13306/cc_api_test?useSSL=false&serverTimezone=Asia/Shanghai","root","");}
 @org.springframework.context.annotation.Bean public JdbcTemplate db(javax.sql.DataSource d){return new JdbcTemplate(d);}
 @org.springframework.context.annotation.Bean public org.springframework.jdbc.datasource.DataSourceTransactionManager transactionManager(javax.sql.DataSource d){return new org.springframework.jdbc.datasource.DataSourceTransactionManager(d);}
 @org.springframework.context.annotation.Bean public WalletService wallet(){return new WalletService();}
 @org.springframework.context.annotation.Bean public MerchantApiService api(){return new MerchantApiService();}
 @org.springframework.context.annotation.Bean public MerchantGatewayController gateway(){return new MerchantGatewayController();}}
 static com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper();
 static JsonNode signed(MerchantGatewayController g,String action,String body,String id,String secret)throws Exception{String time=String.valueOf(Instant.now().getEpochSecond()),nonce=UUID.randomUUID().toString();return json.readTree(g.dispatch(action,body,id,time,nonce,ApiSecurity.sign(secret,time,nonce,"/api/v1/merchant/"+action,body)).getBody());}

 static int n;static void check(boolean value,String name){if(!value)throw new AssertionError(name);n++;System.out.println("PASS "+name);}static Map<String,String> payload(String id,String name,String card,String amount){Map<String,String> p=new LinkedHashMap<>();p.put("merchantId",id);p.put("merchantName",name);p.put("merchantSerialNo","M"+UUID.randomUUID().toString());p.put("cardNo",card);p.put("amount",amount);p.put("occurredAt",OffsetDateTime.now(ZoneId.of("Asia/Shanghai")).withNano(0).toString());p.put("location","商户收银台");p.put("description","商户本地消费业务");return p;}static String raw(Object p)throws Exception{return json.writeValueAsString(p);}static JsonNode call(MerchantGatewayController g,String action,Object p,String id,String secret)throws Exception{return signed(g,action,raw(p),id,secret);}
 public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(Config.class)){JdbcTemplate db=c.getBean(JdbcTemplate.class);WalletService w=c.getBean(WalletService.class);MerchantApiService api=c.getBean(MerchantApiService.class);MerchantGatewayController g=c.getBean(MerchantGatewayController.class);long mid=System.currentTimeMillis(),user=mid+1;String student="SYNC"+mid,card="CC"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT);db.update("insert into sys_user(user_id,login_name,user_name,status,del_flag) values(?,?,'同步支付测试','0','0')",user,student);db.update("insert into campus_card(user_id,card_no) values(?,?)",user,card);db.update("insert into campus_wallet(user_id,student_no,balance) values(?,?,20)",user,student);db.update("insert into campus_person_identity(user_id,identity_no) values(?,'11010519491231002X')",user);db.update("insert into campus_merchant(id,name,active) values(?,'同步支付商户',1)",mid);api.ensure(mid);String id=(String)api.config(mid).get("public_id"),secret=api.rotate(mid,1);api.configure(mid,true,false,true,"",1);Map<String,String> balance=new LinkedHashMap<>();balance.put("merchantId",id);balance.put("cardNo",card);JsonNode before=call(g,"balance",balance,id,secret);check("20.00".equals(before.path("data").path("availableBalance").asText())&&before.path("data").path("canPay").asBoolean(),"signed card balance lookup");check(db.queryForObject("select count(*) from campus_api_order where merchant_id=?",Integer.class,mid)==0,"balance lookup creates no payment order");Map<String,String> p=payload(id,"同步支付商户",card,"1.25");JsonNode paid=call(g,"pay",p,id,secret);if(!"SUCCESS".equals(paid.path("code").asText()))throw new AssertionError(paid.toString());String order=paid.path("data").path("campusOrderNo").asText();check(order.startsWith("DD")&&"SUCCESS".equals(paid.path("data").path("status").asText()),"single pay call allocates campus order and returns completed result");check(p.get("merchantSerialNo").equals(paid.path("data").path("merchantSerialNo").asText())&&!paid.path("data").has("transactionNo"),"merchant serial and campus order are distinct external identifiers");check("18.75".equals(paid.path("data").path("balanceAfter").asText())&&new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"success response follows actual debit commit");check(order.equals(call(g,"pay",p,id,secret).path("data").path("campusOrderNo").asText())&&new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"same merchant serial retry returns original order without double debit");Map<String,String> q=new LinkedHashMap<>();q.put("merchantId",id);q.put("merchantSerialNo",p.get("merchantSerialNo"));check(order.equals(call(g,"query",q,id,secret).path("data").path("campusOrderNo").asText()),"query by merchant serial supports timeout reconciliation");q.remove("merchantSerialNo");q.put("campusOrderNo",order);check("SUCCESS".equals(call(g,"query",q,id,secret).path("data").path("status").asText()),"query by campus order supported");Map<String,String> changed=new LinkedHashMap<>(p);changed.put("amount","2.00");check("INVALID_REQUEST".equals(call(g,"pay",changed,id,secret).path("code").asText()),"same merchant serial cannot change amount");Map<String,String> expensive=payload(id,"同步支付商户",card,"100.00");JsonNode failed=call(g,"pay",expensive,id,secret);check("TRADE_FAILED".equals(failed.path("code").asText())&&failed.path("data").path("campusOrderNo").asText().startsWith("DD"),"insufficient funds synchronously returns failed campus order");check(new BigDecimal("18.75").compareTo((BigDecimal)w.info(user).get("balance"))==0,"failed consumption leaves wallet intact");w.status(user,"LOST");JsonNode lost=call(g,"balance",balance,id,secret);check(!lost.path("data").path("canPay").asBoolean()&&"0.00".equals(lost.path("data").path("availableBalance").asText()),"lost wallet balance query marks no payable funds");check("TRADE_FAILED".equals(call(g,"pay",payload(id,"同步支付商户",card,"1.00"),id,secret).path("code").asText()),"lost wallet rejects merchant consumption");Map<String,String> recharge=payload(id,"同步支付商户",card,"5.00");check("INVALID_REQUEST".equals(call(g,"recharge",recharge,id,secret).path("code").asText()),"recharge requires separate authorization");api.configure(mid,true,true,true,"",1);JsonNode charged=call(g,"recharge",recharge,id,secret);check("SUCCESS".equals(charged.path("code").asText())&&"23.75".equals(charged.path("data").path("balanceAfter").asText()),"authorized recharge synchronously completes while lost");check(db.queryForObject("select count(*) from campus_recharge_order where order_no=?",Integer.class,charged.path("data").path("campusOrderNo").asText())==1,"recharge reuses internal ledger logic and campus order");w.status(user,"ACTIVE");Map<String,String> concurrent=payload(id,"同步支付商户",card,"0.50");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);List<Future<JsonNode>> fs=new ArrayList<>();for(int i=0;i<2;i++)fs.add(pool.submit(()->{gate.await();return call(g,"pay",concurrent,id,secret);}));gate.countDown();String first=null;for(Future<JsonNode> f:fs){JsonNode r=f.get();if(!"SUCCESS".equals(r.path("code").asText()))throw new AssertionError(r.toString());String number=r.path("data").path("campusOrderNo").asText();if(first==null)first=number;else if(!first.equals(number))throw new AssertionError();}pool.shutdown();check(new BigDecimal("23.25").compareTo((BigDecimal)w.info(user).get("balance"))==0,"concurrent direct pay requests debit once");check(db.queryForObject("select count(*) from campus_api_outbox where merchant_id=?",Integer.class,mid)==0,"no asynchronous result push is created");db.update("delete from campus_card where user_id=?",user);check("INVALID_REQUEST".equals(call(g,"balance",balance,id,secret).path("code").asText()),"cancelled card balance lookup rejected");check(db.queryForObject("select count(*) from campus_api_log where public_id=? and code<>'SUCCESS'",Integer.class,id)>=4,"failure logs persisted");String timestamp=String.valueOf(Instant.now().getEpochSecond()),nonce=UUID.randomUUID().toString(),body=raw(q),sign=ApiSecurity.sign(secret,timestamp,nonce,"/api/v1/merchant/query",body);g.dispatch("query",body,id,timestamp,nonce,sign);check(g.dispatch("query",body,id,timestamp,nonce,sign).getStatusCodeValue()==401,"signed nonce replay still rejected");System.out.println("PASS TOTAL "+n);}}
}
